/**
 * Dynamic Favicon Badge Utility (v2 - Bulletproof)
 * Renders a notification badge onto the site favicon using HTML5 Canvas.
 */

export const updateFaviconBadge = (count) => {
  const favicon = document.getElementById('favicon');
  if (!favicon) return;

  const canvas = document.createElement('canvas');
  canvas.width = 32;
  canvas.height = 32;
  const ctx = canvas.getContext('2d');

  const img = new Image();
  // Adding crossOrigin to prevent tainted canvas errors in some browsers
  img.crossOrigin = "anonymous";
  img.src = '/luc.ico'; 

  img.onload = () => {
    try {
      // Clear canvas
      ctx.clearRect(0, 0, 32, 32);
      
      // 1. Draw the original favicon
      ctx.drawImage(img, 0, 0, 32, 32);

      if (count > 0) {
        // 2. Draw Badge Background (Bottom Right - Flat Design)
        const radius = 10; 
        const x = 32 - radius;
        const y = 32 - radius;

        ctx.beginPath();
        ctx.arc(x, y, radius, 0, 2 * Math.PI, false);
        ctx.fillStyle = '#EF4444'; // LUC Hub Brand Red
        ctx.fill();

        // 3. Draw Badge Text
        ctx.fillStyle = 'white';
        ctx.font = 'bold 11px Inter, system-ui, sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        
        const displayCount = count > 99 ? '99+' : count;
        ctx.fillText(displayCount, x, y + 1);
      }

      // 4. Update the link tag with the new data URL
      favicon.href = canvas.toDataURL('image/png');
    } catch (err) {
      console.warn("Favicon badge update failed:", err);
    }
  };

  img.onerror = () => {
    console.warn("Failed to load favicon image for badge update.");
  };
};
