import React, { useState, useEffect } from 'react';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Icon from '../../../components/AppIcon';
import DynamicListInput from '../../../components/ui/DynamicListInput';
import { Checkbox } from '../../../components/ui/Checkbox';
import { supabaseService } from '../../../services/supabaseService';

const OpportunityModal = ({ isOpen, onClose, onSubmit, initialData }) => {
    const [activeTab, setActiveTab] = useState('basic');
    const [formData, setFormData] = useState({
        title: '',
        organization: '',
        category: 'scholarships',
        type: 'Program',
        status: 'active',
        deadline: '',
        location: 'Remote',
        stipend: 'Unpaid',
        image: '',
        organizationLogo: '',
        verified: false,
        trending: false,
        tags: '',
        // New Fields
        shortDescription: '',
        detailedDescription: '',
        fundingType: 'Full Funding',
        applicationLink: '',
        benefitsList: [],
        requirementsList: [],
        processList: [],
        duration: '',
        educationLevel: '',
        eligibility: '',
        language: '',
    });
    const [uploading, setUploading] = useState(false);
    const [uploadError, setUploadError] = useState(null);

    useEffect(() => {
        if (initialData) {
            setFormData({
                ...initialData,
                tags: initialData.tags ? (Array.isArray(initialData.tags) ? initialData.tags.join(', ') : initialData.tags) : '',
                benefitsList: initialData.benefitsList || [],
                requirementsList: initialData.requirementsList || [],
                processList: initialData.processList || [],
                shortDescription: initialData.shortDescription || '',
                detailedDescription: initialData.detailedDescription || '',
                fundingType: initialData.fundingType || 'Full Funding',
                applicationLink: initialData.applicationLink || '',
                duration: initialData.duration || '',
                educationLevel: initialData.educationLevel || '',
                eligibility: initialData.eligibility || '',
                language: initialData.language || 'English',
            });
        } else {
            setFormData({
                title: '',
                organization: '',
                category: 'scholarships',
                type: 'Program',
                status: 'active',
                deadline: '',
                location: 'Remote',
                stipend: 'Unpaid',
                image: '',
                organizationLogo: '',
                verified: false,
                trending: false,
                tags: '',
                shortDescription: '',
                detailedDescription: '',
                fundingType: 'Full Funding',
                applicationLink: '',
                benefitsList: [],
                requirementsList: [],
                processList: [],
                duration: '',
                educationLevel: '',
                eligibility: '',
                language: 'English',
            });
        }
        setActiveTab('basic');
    }, [initialData, isOpen]);

    if (!isOpen) return null;

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const handleListChange = (field, newList) => {
        setFormData(prev => ({
            ...prev,
            [field]: newList
        }));
    };

    const handleImageUpload = async (e, field) => {
        const file = e.target.files[0];
        if (!file) return;

        setUploading(true);
        setUploadError(null);
        try {
            console.log(`Starting upload for ${field}...`);
            const publicUrl = await supabaseService.uploadImage(file);
            console.log("Upload successful:", publicUrl);
            setFormData(prev => ({
                ...prev,
                [field]: publicUrl
            }));
        } catch (error) {
            console.error("Upload failed details:", error);
            const errorMsg = error.message || JSON.stringify(error) || "Unknown upload error";
            setUploadError(`Failed to upload to '${field}': ${errorMsg}`);
        } finally {
            setUploading(false);
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        const submissionData = {
            ...formData,
            tags: formData.tags.split(',').map(t => t.trim()).filter(Boolean)
        };
        onSubmit(submissionData);
        onClose();
    };

    const tabs = [
        { id: 'basic', label: 'Basic Info', icon: 'Layout' },
        { id: 'details', label: 'Details', icon: 'FileText' },
        { id: 'lists', label: 'Lists & Requirements', icon: 'List' },
    ];

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
            <div className="bg-background rounded-2xl shadow-xl w-full max-w-4xl max-h-[90vh] flex flex-col border border-border">
                {/* Header */}
                <div className="p-6 border-b border-border flex justify-between items-center bg-background rounded-t-2xl z-10 shrink-0">
                    <div>
                        <h2 className="text-xl font-bold">{initialData ? 'Edit Opportunity' : 'Add New Opportunity'}</h2>
                        <p className="text-sm text-muted-foreground mt-1">Manage all details for this opportunity</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-muted rounded-full">
                        <Icon name="X" size={20} />
                    </button>
                </div>

                {/* Body */}
                <div className="flex-1 overflow-hidden flex flex-col md:flex-row">
                    {/* Sidebar Tabs */}
                    <div className="w-full md:w-64 bg-muted/30 border-r border-border p-4 flex flex-row md:flex-col gap-2 overflow-x-auto md:overflow-visible shrink-0">
                        {tabs.map(tab => (
                            <button
                                key={tab.id}
                                type="button"
                                onClick={() => setActiveTab(tab.id)}
                                className={`flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap
                                    ${activeTab === tab.id ? 'bg-primary text-primary-foreground' : 'hover:bg-muted text-muted-foreground hover:text-foreground'}
                                `}
                            >
                                <Icon name={tab.icon} size={18} />
                                {tab.label}
                            </button>
                        ))}
                    </div>

                    {/* Content Area */}
                    <div className="flex-1 overflow-y-auto p-6">
                        <form id="opportunity-form" onSubmit={handleSubmit} className="space-y-6">
                            {/* TAB: BASIC INFO */}
                            {activeTab === 'basic' && (
                                <div className="space-y-6">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        <div className="space-y-4">
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Title</label>
                                                <Input name="title" value={formData.title} onChange={handleChange} required placeholder="e.g. Google Summer of Code" />
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Organization</label>
                                                <Input name="organization" value={formData.organization} onChange={handleChange} required placeholder="e.g. Google" />
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Location</label>
                                                <Input name="location" value={formData.location} onChange={handleChange} placeholder="e.g. Remote, London, UK" />
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Stipend / Benefits Short</label>
                                                <Input name="stipend" value={formData.stipend} onChange={handleChange} placeholder="e.g. $5,000, Full Funding" />
                                            </div>
                                        </div>

                                        <div className="space-y-4">
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Category</label>
                                                <select
                                                    name="category"
                                                    value={formData.category}
                                                    onChange={handleChange}
                                                    className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                                                >
                                                    <option value="scholarships">Scholarships</option>
                                                    <option value="internships">Internships</option>
                                                    <option value="fellowships">Fellowships</option>
                                                    <option value="competitions">Competitions</option>
                                                    <option value="workshops">Workshops</option>
                                                    <option value="conferences">Conferences</option>
                                                    <option value="jobs">Jobs</option>
                                                </select>
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Type Label</label>
                                                <Input name="type" value={formData.type} onChange={handleChange} placeholder="e.g. Scholarship, Internship" />
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Status</label>
                                                <select
                                                    name="status"
                                                    value={formData.status}
                                                    onChange={handleChange}
                                                    className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                                                >
                                                    <option value="active">Active</option>
                                                    <option value="pending">Pending</option>
                                                    <option value="draft">Draft</option>
                                                    <option value="expired">Expired</option>
                                                </select>
                                            </div>
                                            <div>
                                                <label className="block text-sm font-medium mb-1">Deadline</label>
                                                <Input name="deadline" value={formData.deadline} onChange={handleChange} placeholder="e.g. 2026-05-15, Rolling" />
                                            </div>
                                        </div>
                                    </div>

                                    {/* Key Info Row */}
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-4">
                                        <div>
                                            <label className="block text-sm font-medium mb-1">Duration</label>
                                            <Input name="duration" value={formData.duration} onChange={handleChange} placeholder="e.g. 1-2 Years" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium mb-1">Education Level</label>
                                            <Input name="educationLevel" value={formData.educationLevel} onChange={handleChange} placeholder="e.g. Master's & PhD" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium mb-1">Eligibility</label>
                                            <Input name="eligibility" value={formData.eligibility} onChange={handleChange} placeholder="e.g. International Students" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium mb-1">Language</label>
                                            <Input name="language" value={formData.language} onChange={handleChange} placeholder="e.g. English" />
                                        </div>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium mb-1">Organization Logo</label>
                                        <div className="flex gap-2 items-center mb-2">
                                            <input
                                                type="file"
                                                accept="image/*"
                                                onChange={(e) => handleImageUpload(e, 'organizationLogo')}
                                                className="block w-full text-sm text-foreground/60
                                                file:mr-4 file:py-2 file:px-4
                                                file:rounded-full file:border-0
                                                file:text-sm file:font-semibold
                                                file:bg-primary/10 file:text-primary
                                                dark:file:bg-primary/20 dark:file:text-brand-blue
                                                hover:file:bg-primary/20
                                                cursor-pointer
                                                "
                                                disabled={uploading}
                                            />
                                            {uploading && <span className="text-sm text-muted-foreground animate-pulse">Uploading...</span>}
                                            {formData.organizationLogo && <img src={formData.organizationLogo} alt="Preview" className="h-10 w-10 object-cover rounded border border-border" />}
                                        </div>
                                    </div>

                                    <div>
                                        <label className="block text-sm font-medium mb-1">Hero Image</label>
                                        <div className="flex gap-2 items-center mb-2">
                                            <input
                                                type="file"
                                                accept="image/*"
                                                onChange={(e) => handleImageUpload(e, 'image')}
                                                className="block w-full text-sm text-foreground/60
                                                file:mr-4 file:py-2 file:px-4
                                                file:rounded-full file:border-0
                                                file:text-sm file:font-semibold
                                                file:bg-primary/10 file:text-primary
                                                dark:file:bg-primary/20 dark:file:text-brand-blue
                                                hover:file:bg-primary/20
                                                cursor-pointer
                                                "
                                                disabled={uploading}
                                            />
                                            {uploading && <span className="text-sm text-muted-foreground animate-pulse">Uploading...</span>}
                                            {formData.image && <img src={formData.image} alt="Preview" className="h-10 w-10 object-cover rounded border border-border" />}
                                        </div>
                                    </div>

                                    <div className="flex gap-8 p-6 bg-muted/20 rounded-2xl border border-border mt-4">
                                        <Checkbox
                                            label="Verified Opportunity"
                                            description="Display a verified badge to build trust"
                                            name="verified"
                                            checked={formData.verified}
                                            onChange={(e) => setFormData({ ...formData, verified: e.target.checked })}
                                        />
                                        <Checkbox
                                            label="Mark as Trending"
                                            description="Highlight this on the homepage"
                                            name="trending"
                                            checked={formData.trending}
                                            onChange={(e) => setFormData({ ...formData, trending: e.target.checked })}
                                        />
                                    </div>
                                </div>
                            )}

                            {/* TAB: DETAILS */}
                            {activeTab === 'details' && (
                                <div className="space-y-6">
                                    <div>
                                        <label className="block text-sm font-medium mb-1">Short Description</label>
                                        <textarea
                                            name="shortDescription"
                                            value={formData.shortDescription}
                                            onChange={handleChange}
                                            rows={2}
                                            className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none resize-none"
                                            placeholder="Brief summary for cards..."
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1">Detailed Description</label>
                                        <textarea
                                            name="detailedDescription"
                                            value={formData.detailedDescription}
                                            onChange={handleChange}
                                            rows={8}
                                            className="w-full px-4 py-2 bg-muted border border-border rounded-lg focus:ring-2 focus:ring-primary outline-none"
                                            placeholder="Full details about the opportunity..."
                                        />
                                    </div>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                        <div>
                                            <label className="block text-sm font-medium mb-1">Funding Type</label>
                                            <Input name="fundingType" value={formData.fundingType} onChange={handleChange} placeholder="e.g. Full Funding, Partial Funding" />
                                        </div>
                                        <div>
                                            <label className="block text-sm font-medium mb-1">Application Link (External)</label>
                                            <Input name="applicationLink" value={formData.applicationLink} onChange={handleChange} placeholder="https://..." />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium mb-1">Tags (comma separated)</label>
                                        <Input name="tags" value={formData.tags} onChange={handleChange} placeholder="Technology, Education, Design" />
                                    </div>
                                </div>
                            )}

                            {/* TAB: LISTS */}
                            {activeTab === 'lists' && (
                                <div className="space-y-8">
                                    <DynamicListInput
                                        label="Benefits / What's Included"
                                        items={formData.benefitsList}
                                        onChange={(newList) => handleListChange('benefitsList', newList)}
                                        placeholder="Add benefit..."
                                    />
                                    <DynamicListInput
                                        label="Eligibility Requirements"
                                        items={formData.requirementsList}
                                        onChange={(newList) => handleListChange('requirementsList', newList)}
                                        placeholder="Add requirement..."
                                    />
                                    <DynamicListInput
                                        label="Application Process Steps"
                                        items={formData.processList}
                                        onChange={(newList) => handleListChange('processList', newList)}
                                        placeholder="Add step..."
                                    />
                                </div>
                            )}
                        </form>
                    </div>
                </div>

                {/* Footer */}
                <div className="p-6 border-t border-border bg-background flex justify-between items-center rounded-b-2xl shrink-0">
                    <div className="flex-1">
                        {uploadError && (
                            <div className="text-destructive text-sm font-medium">
                                Error: {uploadError}
                            </div>
                        )}
                    </div>
                    <div className="flex gap-3">
                        <Button type="button" variant="ghost" onClick={onClose} disabled={uploading}>Cancel</Button>
                        <Button
                            type="submit"
                            form="opportunity-form"
                            variant="default"
                            disabled={uploading}
                        >
                            {uploading ? 'Uploading...' : 'Save Opportunity'}
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default OpportunityModal;
