import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import { useToast } from '../../../contexts/ToastContext';

const VentureOversight = () => {
    const { addToast } = useToast();
    const [activeTab, setActiveTab] = useState('pitches'); // pitches | squads | proof_of_work
    const [pitches, setPitches] = useState([]);
    const [squads, setSquads] = useState([]);
    const [proofOfWorks, setProofOfWorks] = useState([]);
    const [wins, setWins] = useState([]);
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        fetchData();
    }, [activeTab]);

    const fetchData = async () => {
        setIsLoading(true);
        try {
            if (activeTab === 'pitches') {
                const data = await supabaseService.adminGetAllPitches();
                setPitches(data || []);
            } else if (activeTab === 'squads') {
                const data = await supabaseService.adminGetAllSquads();
                setSquads(data || []);
            } else if (activeTab === 'proof_of_work') {
                const data = await supabaseService.adminGetProofOfWork();
                setProofOfWorks(data || []);
            } else if (activeTab === 'wins') {
                // Mock data since we haven't created the table yet
                setWins([
                    {
                        id: 'win-1',
                        user: { full_name: 'David O.' },
                        title: 'Hired as Junior Dev at Google',
                        type: 'job',
                        status: 'pending',
                        created_at: new Date().toISOString()
                    }
                ]);
            }
        } catch (error) {
            console.error("Admin fetch error:", error);
            // Fallback to empty if table doesn't exist yet
            if (activeTab === 'pitches') setPitches([]);
            else if (activeTab === 'squads') setSquads([]);
            else if (activeTab === 'proof_of_work') setProofOfWorks([]);
            else setWins([]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleAction = async (id, action) => {
        try {
            const status = action === 'approve' ? 'approved' : 'rejected';
            
            if (activeTab === 'pitches') {
                await supabaseService.adminUpdatePitchStatus(id, status);
            } else if (activeTab === 'proof_of_work') {
                await supabaseService.adminUpdateProofOfWorkStatus(id, status);
            } else if (activeTab === 'wins') {
                setWins(wins.map(w => w.id === id ? { ...w, status } : w));
            }

            addToast(`${activeTab.replace('_', ' ')} ${action === 'approve' ? 'Approved' : 'Rejected'} successfully!`, 'success');
            fetchData();
        } catch (err) {
            addToast('Action failed', 'error');
        }
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-end">
                <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-xl border border-slate-200 dark:border-white/10">
                    <button 
                        onClick={() => setActiveTab('pitches')}
                        className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'pitches' ? 'bg-white dark:bg-white/10 shadow-sm text-primary' : 'text-slate-500'}`}
                    >
                        Idea Pitches
                    </button>
                    <button 
                        onClick={() => setActiveTab('squads')}
                        className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'squads' ? 'bg-white dark:bg-white/10 shadow-sm text-primary' : 'text-slate-500'}`}
                    >
                        Active Squads
                    </button>
                    <button 
                        onClick={() => setActiveTab('proof_of_work')}
                        className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'proof_of_work' ? 'bg-white dark:bg-white/10 shadow-sm text-primary' : 'text-slate-500'}`}
                    >
                        Proof of Work
                    </button>
                    <button 
                        onClick={() => setActiveTab('wins')}
                        className={`px-6 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all ${activeTab === 'wins' ? 'bg-white dark:bg-white/10 shadow-sm text-primary' : 'text-slate-500'}`}
                    >
                        Ground Truth Wins
                    </button>
                </div>
            </div>

            {isLoading ? (
                <div className="flex justify-center py-20">
                    <Icon name="RefreshCw" className="animate-spin text-primary" size={40} />
                </div>
            ) : (
                <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-white/5 overflow-hidden shadow-sm">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50 dark:bg-white/5 border-b border-slate-200 dark:border-white/5">
                                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Project / Venture</th>
                                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Lead / Founder</th>
                                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Category</th>
                                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500">Status</th>
                                <th className="p-6 text-[10px] font-black uppercase tracking-widest text-slate-500 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 dark:divide-white/5">
                            {activeTab === 'pitches' ? (
                                pitches.map(pitch => (
                                    <tr key={pitch.id} className="hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors">
                                        <td className="p-6">
                                            <p className="font-bold text-slate-900 dark:text-white">{pitch.title}</p>
                                            <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Submitted {pitch.created_at}</p>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center text-[10px] font-black text-primary">
                                                    {(pitch.founder?.full_name || pitch.user_id || 'U')[0]}
                                                </div>
                                                <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                                    {pitch.founder?.full_name || `User ID: ${pitch.user_id?.substring(0, 8)}...`}
                                                </span>
                                            </div>
                                        </td>
                                        <td className="p-6">
                                            <span className="px-3 py-1 bg-slate-100 dark:bg-white/5 rounded-lg text-[9px] font-black uppercase tracking-widest text-slate-500">
                                                {pitch.sector}
                                            </span>
                                        </td>
                                        <td className="p-6">
                                            <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                                                pitch.status === 'approved' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-amber-500/10 text-amber-500'
                                            }`}>
                                                {pitch.status}
                                            </span>
                                        </td>
                                        <td className="p-6 text-right">
                                            <div className="flex items-center justify-end gap-2">
                                                <Button size="sm" variant="ghost" className="text-emerald-500" onClick={() => handleAction(pitch.id, 'approve')}>
                                                    <Icon name="Check" size={16} />
                                                </Button>
                                                <Button size="sm" variant="ghost" className="text-red-500" onClick={() => handleAction(pitch.id, 'reject')}>
                                                    <Icon name="X" size={16} />
                                                </Button>
                                                <Button size="sm" variant="outline" className="text-xs font-black italic">View Deck</Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            ) : activeTab === 'wins' ? (
                                wins.map(win => (
                                    <tr key={win.id} className="hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors">
                                        <td className="p-6">
                                            <p className="font-bold text-slate-900 dark:text-white truncate max-w-[200px]">{win.title}</p>
                                            <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Logged {new Date(win.created_at).toLocaleDateString()}</p>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-amber-500/10 flex items-center justify-center text-[10px] font-black text-amber-500">
                                                    {(win.user?.full_name || 'U')[0]}
                                                </div>
                                                <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                                    {win.user?.full_name || 'User'}
                                                </span>
                                            </div>
                                        </td>
                                        <td className="p-6">
                                            <span className="px-3 py-1 bg-slate-100 dark:bg-white/5 rounded-lg text-[9px] font-black uppercase tracking-widest text-slate-500">
                                                {win.type}
                                            </span>
                                        </td>
                                        <td className="p-6">
                                            <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                                                win.status === 'approved' ? 'bg-emerald-500/10 text-emerald-500' : 
                                                win.status === 'rejected' ? 'bg-rose-500/10 text-rose-500' : 'bg-amber-500/10 text-amber-500'
                                            }`}>
                                                {win.status}
                                            </span>
                                        </td>
                                        <td className="p-6 text-right">
                                            <div className="flex items-center justify-end gap-2">
                                                <Button size="sm" variant="ghost" className="text-emerald-500" onClick={() => handleAction(win.id, 'approve')}>
                                                    <Icon name="Check" size={16} />
                                                </Button>
                                                <Button size="sm" variant="ghost" className="text-red-500" onClick={() => handleAction(win.id, 'reject')}>
                                                    <Icon name="X" size={16} />
                                                </Button>
                                                <Button size="sm" variant="outline" className="text-xs font-black italic">View Proof</Button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            ) : activeTab === 'proof_of_work' ? (
                                proofOfWorks.map(pow => (
                                    <tr key={pow.id} className="hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors">
                                        <td className="p-6">
                                            <p className="font-bold text-slate-900 dark:text-white truncate max-w-[200px]">{pow.project_name || 'Untitled Project'}</p>
                                            <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Submitted {new Date(pow.created_at).toLocaleDateString()}</p>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex items-center gap-3">
                                                <div className="w-8 h-8 rounded-full bg-secondary/10 flex items-center justify-center text-[10px] font-black text-secondary">
                                                    {(pow.student?.full_name || 'S')[0]}
                                                </div>
                                                <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                                    {pow.student?.full_name || 'Scholar'}
                                                </span>
                                            </div>
                                        </td>
                                        <td className="p-6">
                                            <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                                                pow.type === 'squad' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-brand-blue/10 text-brand-blue'
                                            }`}>
                                                {pow.type || 'Course Project'}
                                            </span>
                                        </td>
                                        <td className="p-6">
                                            <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${
                                                pow.status === 'approved' ? 'bg-emerald-500/10 text-emerald-500' : 'bg-amber-500/10 text-amber-500'
                                            }`}>
                                                {pow.status}
                                            </span>
                                        </td>
                                        <td className="p-6 text-right">
                                            <div className="flex items-center justify-end gap-2">
                                                <Button size="sm" variant="ghost" className="text-emerald-500" onClick={() => handleAction(pow.id, 'approve')}>
                                                    <Icon name="Check" size={16} />
                                                </Button>
                                                <Button size="sm" variant="ghost" className="text-red-500" onClick={() => handleAction(pow.id, 'reject')}>
                                                    <Icon name="X" size={16} />
                                                </Button>
                                                <a href={pow.url} target="_blank" rel="noopener noreferrer">
                                                    <Button size="sm" variant="outline" className="text-xs font-black italic">Open URL</Button>
                                                </a>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                squads.map(squad => (
                                    <tr key={squad.id} className="hover:bg-slate-50 dark:hover:bg-white/[0.02] transition-colors">
                                        <td className="p-6">
                                            <p className="font-bold text-slate-900 dark:text-white">{squad.name}</p>
                                            <p className="text-[10px] text-slate-500 uppercase tracking-tighter">{squad.members} Builders Active</p>
                                        </td>
                                        <td className="p-6">
                                            <span className="text-sm font-medium text-slate-700 dark:text-slate-300">
                                                {squad.creator?.full_name || (squad.creator_id ? `ID: ${squad.creator_id.substring(0, 8)}...` : 'System User')}
                                            </span>
                                        </td>
                                        <td className="p-6">
                                            <span className="px-3 py-1 bg-emerald-500/10 rounded-lg text-[9px] font-black uppercase tracking-widest text-emerald-500 border border-emerald-500/20">
                                                {squad.mission}
                                            </span>
                                        </td>
                                        <td className="p-6">
                                            <div className="flex items-center gap-2">
                                                <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping" />
                                                <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">{squad.status}</span>
                                            </div>
                                        </td>
                                        <td className="p-6 text-right">
                                            <Button size="sm" variant="outline" className="text-xs font-black italic">Manage Squad</Button>
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                    
                    {((activeTab === 'pitches' && pitches.length === 0) || (activeTab === 'squads' && squads.length === 0) || (activeTab === 'proof_of_work' && proofOfWorks.length === 0) || (activeTab === 'wins' && wins.length === 0)) && (
                        <div className="py-20 text-center">
                            <Icon name="Inbox" size={48} className="text-slate-300 mx-auto mb-4" />
                            <p className="text-slate-500 font-medium">No pending {activeTab.replace('_', ' ')} found.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default VentureOversight;
