import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';

const SystemSettings = () => {
    const { addToast } = useToast();
    const [settings, setSettings] = useState({ is_hub_announced: false });
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        fetchSettings();
    }, []);

    const fetchSettings = async () => {
        try {
            const data = await supabaseService.getSiteSettings();
            if (data) setSettings(data);
        } catch (err) {
            console.error("Settings load error:", err);
            addToast("Failed to load system settings.", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleToggleHub = async () => {
        setIsSaving(true);
        const newValue = !settings.is_hub_announced;
        try {
            await supabaseService.updateSiteSettings({ is_hub_announced: newValue });
            setSettings(prev => ({ ...prev, is_hub_announced: newValue }));
            addToast(
                newValue 
                    ? "Community Hub Announcement ENABLED on Contact Page." 
                    : "Community Hub Announcement DISABLED.", 
                "success"
            );
        } catch (err) {
            console.error("Update error:", err);
            addToast("Failed to update setting.", "error");
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) return <div className="p-8 text-center opacity-50">Loading System Controls...</div>;

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-black text-slate-900 dark:text-white uppercase italic tracking-tighter">System Controls</h2>
                    <p className="text-sm text-slate-500 font-medium">Manage global ecosystem announcements and platform state.</p>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Hub Toggle Card */}
                <div className="bg-card border border-border p-8 rounded-[2.5rem] relative overflow-hidden group">
                    <div className="absolute inset-0 bg-primary/5 opacity-0 group-hover:opacity-100 transition-opacity" />
                    
                    <div className="relative z-10 space-y-6">
                        <div className="flex items-center justify-between">
                            <div className="w-14 h-14 bg-primary/10 rounded-2xl flex items-center justify-center text-primary">
                                <Icon name="MapPin" size={28} />
                            </div>
                            <button 
                                onClick={handleToggleHub}
                                disabled={isSaving}
                                className={`relative w-16 h-8 rounded-full transition-colors duration-300 ${settings.is_hub_announced ? 'bg-primary' : 'bg-slate-200 dark:bg-white/10'}`}
                            >
                                <div className={`absolute top-1 left-1 w-6 h-6 bg-white rounded-full shadow-lg transition-transform duration-300 ${settings.is_hub_announced ? 'translate-x-8' : 'translate-x-0'}`} />
                            </button>
                        </div>

                        <div className="space-y-1">
                            <h3 className="text-xl font-black uppercase italic tracking-tight">Community Hub Announcement</h3>
                            <p className="text-xs text-slate-500 font-medium leading-relaxed">
                                Toggle a "Coming Soon" banner for our physical Community Hub on the Contact Page. 
                                Use this to gauge interest for in-person consultations.
                            </p>
                        </div>

                        <div className="pt-4 flex items-center gap-3">
                            <div className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${settings.is_hub_announced ? 'bg-emerald-500/10 text-emerald-500' : 'bg-slate-500/10 text-slate-500'}`}>
                                {settings.is_hub_announced ? 'Publicly Announced' : 'Hidden'}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Placeholder for future settings */}
                <div className="bg-card border border-border border-dashed p-8 rounded-[2.5rem] flex flex-col items-center justify-center text-center opacity-40">
                    <Icon name="PlusCircle" size={32} className="mb-4" />
                    <p className="text-[10px] font-black uppercase tracking-widest">Future System Controls</p>
                    <p className="text-[9px] font-bold">Maintenance Mode, Feature Flags, etc.</p>
                </div>
            </div>
        </div>
    );
};

export default SystemSettings;
