import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate, useLocation } from 'react-router-dom';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import { cn } from '../../utils/cn';
import { normalizeId } from '../../utils/idUtils';
import { getAchievementLabel, getAchievementTier } from '../../utils/courseUtils';
import { fetchSavedOpportunitiesAsync } from '../../store/contentSlice';
import { supabaseService } from '../../services/supabaseService';

// Student Specific Components
import LUCWallet from '../profile/components/LUCWallet';
import ReferralDashboard from '../profile/components/ReferralDashboard';
import StudyMateHub from '../profile/components/StudyMateHub';
import ProjectSquadHub from '../profile/components/ProjectSquadHub';
import FoundersGear from '../profile/components/FoundersGear';
import GoalCenter from '../profile/components/GoalCenter';
import ConsistencyHeatmap from '../profile/components/ConsistencyHeatmap';
import CertificateViewer from '../academy/components/CertificateViewer';
import AnnouncementFeed from '../profile/components/AnnouncementFeed';
import { useToast } from '../../contexts/ToastContext';

const StudentDashboard = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const location = useLocation();
    const { addToast } = useToast();
    const { user, role, roles } = useSelector((state) => state.auth);
    const { academy, vault, savedOpportunities } = useSelector((state) => state.content);
    const { courseProgress, watchHistory } = useSelector((state) => state.activity);

    const isAdmin = role === 'admin' || role === 'moderator' || roles?.includes('admin') || roles?.includes('moderator');
    const isInstructor = role === 'instructor' || role === 'tutor' || roles?.includes('instructor') || roles?.includes('tutor');

    const [activeTab, setActiveTab] = useState(location.state?.tab || 'overview');
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [selectedCert, setSelectedCert] = useState(null);
    const [isCertModalOpen, setIsCertModalOpen] = useState(false);
    const [certificates, setCertificates] = useState([]);

    // Sync tab when navigating from menu
    useEffect(() => {
        if (location.state?.tab) {
            setActiveTab(location.state.tab);
        }
    }, [location.state]);

    // Redirect instructors/admins with no student activity to their primary hub
    useEffect(() => {
        const hasStudentActivity = Object.keys(courseProgress || {}).length > 0;
        const isStaff = isAdmin || isInstructor;

        if (isStaff && !hasStudentActivity && activeTab === 'overview') {
            navigate(isAdmin ? '/admin-dashboard' : '/instructor-dashboard', { replace: true });
        }
    }, [isAdmin, isInstructor, courseProgress, navigate, activeTab]);

    useEffect(() => {
        if (user) {
            dispatch(fetchSavedOpportunitiesAsync(user.id));
            const fetchCertificates = async () => {
                try {
                    const certs = await supabaseService.getStudentCertificates(user.id);
                    setCertificates(certs || []);
                } catch (err) {
                    console.error("Failed to fetch certificates:", err);
                }
            };
            fetchCertificates();
        }
    }, [dispatch, user]);

    // Computed Learning Progress
    const enrolledCourses = Object.keys(courseProgress).map(courseId => {
        const stringId = normalizeId(courseId);
        const course = [...(academy || []), ...(vault || [])].find(c => c && normalizeId(c.id) === stringId);
        if (!course) return null;
        return {
            ...course,
            progress: courseProgress[courseId].percentage,
            lastAccessed: courseProgress[courseId].lastAccessed,
            tier: getAchievementTier(course),
            achievementLabel: getAchievementLabel(course)
        };
    }).filter(Boolean);

    const totalCourses = enrolledCourses.length;
    const avgProgress = totalCourses > 0
        ? Math.round(enrolledCourses.reduce((acc, curr) => acc + curr.progress, 0) / totalCourses)
        : 0;

    let scholarLevel = "Novice Scholar";
    if (avgProgress > 25) scholarLevel = "Apprentice Scholar";
    if (avgProgress > 50) scholarLevel = "Dedicated Scholar";
    if (avgProgress > 80) scholarLevel = "Master Scholar";
    if (avgProgress === 100) scholarLevel = "Grandmaster";

    const getGreeting = () => {
        if (user?.created_at) {
            const created = new Date(user.created_at);
            const now = new Date();
            const diffInHours = (now - created) / (1000 * 60 * 60);
            if (diffInHours < 24) return 'Welcome Aboard,';
        }

        const hour = new Date().getHours();
        if (hour < 12) return 'Good Morning,';
        if (hour < 18) return 'Good Afternoon,';
        return 'Good Evening,';
    };

    const navigationGroups = [
        {
            group: 'MY ACADEMY',
            tabs: [
                { id: 'overview', label: 'Overview', icon: 'LayoutDashboard' },
                { id: 'learning', label: 'My Learning', icon: 'GraduationCap' },
                { id: 'goals', label: 'Goal Engine', icon: 'Target' },
                { id: 'badges', label: 'Achievements', icon: 'Award' },
            ]
        },
        {
            group: 'NETWORK & SOCIAL',
            tabs: [
                { id: 'study-mates', label: 'Study Mates', icon: 'Users' },
                { id: 'project-squads', label: 'Project Squads', icon: 'Rocket' },
                { id: 'referral', label: 'Invite & Earn', icon: 'UserPlus' },
                { id: 'saved', label: 'Saved Ops', icon: 'Bookmark' },
            ]
        },
        {
            group: 'ECOSYSTEM',
            tabs: [
                { id: 'luc-wallet', label: 'LUC Wallet', icon: 'Coins' },
                { id: 'gear', label: 'Founders Gear', icon: 'ShoppingBag' },
            ]
        }
    ];

    const renderTabContent = () => {
        switch (activeTab) {
            case 'overview':
                return (
                    <div className="space-y-8 animate-in fade-in duration-700">
                        {/* Welcome Card */}
                        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                            <div className="lg:col-span-2 bg-card border border-border rounded-[2.5rem] p-8 shadow-xl relative overflow-hidden group">
                                <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:opacity-[0.05] transition-opacity duration-500">
                                    <Icon name="GraduationCap" size={200} />
                                </div>
                                <div className="relative z-10 space-y-6">
                                    <div className="flex items-center gap-3">
                                        <div className="h-1 w-12 bg-secondary rounded-full" />
                                        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-secondary">Academic Standing</span>
                                    </div>
                                    <div>
                                        <h2 className="text-3xl font-black italic tracking-tighter uppercase leading-none mb-2">{getGreeting()} {user?.name?.split(' ')[0]}</h2>
                                        <p className="text-muted-foreground font-bold italic opacity-70">Continue your journey towards global excellence.</p>
                                    </div>
                                    <div className="flex flex-wrap gap-4">
                                        <div className="px-6 py-3 bg-muted/50 rounded-2xl border border-border/50">
                                            <p className="text-[10px] font-black text-muted-foreground uppercase tracking-widest mb-1">Rank</p>
                                            <p className="text-lg font-black italic text-secondary">{scholarLevel}</p>
                                        </div>
                                        <div className="px-6 py-3 bg-muted/50 rounded-2xl border border-border/50">
                                            <p className="text-[10px] font-black text-muted-foreground uppercase tracking-widest mb-1">Courses</p>
                                            <p className="text-lg font-black italic text-primary">{totalCourses}</p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-xl flex flex-col justify-between">
                                <div className="space-y-4">
                                    <h3 className="text-xl font-black italic tracking-tight uppercase">Average Progress</h3>
                                    <div className="relative h-4 w-full bg-muted rounded-full overflow-hidden border border-border/50 p-1">
                                        <motion.div 
                                            initial={{ width: 0 }}
                                            animate={{ width: `${avgProgress}%` }}
                                            transition={{ duration: 1, ease: "easeOut" }}
                                            className="h-full bg-gradient-to-r from-secondary to-secondary/80 rounded-full"
                                        />
                                    </div>
                                    <p className="text-4xl font-black italic text-secondary">{avgProgress}%</p>
                                </div>
                                <Button variant="secondary" fullWidth onClick={() => setActiveTab('learning')} className="rounded-2xl h-14 font-black italic uppercase tracking-widest">RESUME LEARNING</Button>
                            </div>
                        </div>

                        {/* Secondary Stats */}
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                            <div className="p-6 bg-card border border-border rounded-3xl shadow-sm">
                                <div className="flex items-center gap-4">
                                    <div className="p-3 bg-primary/10 rounded-2xl text-primary"><Icon name="Target" size={24} /></div>
                                    <div>
                                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Active Goals</p>
                                        <p className="text-xl font-black italic">0</p>
                                    </div>
                                </div>
                            </div>
                            <div className="p-6 bg-card border border-border rounded-3xl shadow-sm">
                                <div className="flex items-center gap-4">
                                    <div className="p-3 bg-success/10 rounded-2xl text-success"><Icon name="Award" size={24} /></div>
                                    <div>
                                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Certificates</p>
                                        <p className="text-xl font-black italic">{certificates.length}</p>
                                    </div>
                                </div>
                            </div>
                            <div className="p-6 bg-card border border-border rounded-3xl shadow-sm">
                                <div className="flex items-center gap-4">
                                    <div className="p-3 bg-secondary/10 rounded-2xl text-secondary"><Icon name="Zap" size={24} /></div>
                                    <div>
                                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Quick Wins</p>
                                        <p className="text-xl font-black italic">0</p>
                                    </div>
                                </div>
                            </div>
                            <div className="p-6 bg-card border border-border rounded-3xl shadow-sm">
                                <div className="flex items-center gap-4">
                                    <div className="p-3 bg-amber-500/10 rounded-2xl text-amber-500"><Icon name="Bookmark" size={24} /></div>
                                    <div>
                                        <p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Saved Items</p>
                                        <p className="text-xl font-black italic">{savedOpportunities?.length || 0}</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Heatmap & Activity */}
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                            <ConsistencyHeatmap />
                            <div className="bg-card border border-border rounded-[2.5rem] p-8 shadow-xl">
                                <h3 className="text-xl font-black italic tracking-tight uppercase mb-6">Recent Pursuits</h3>
                                <div className="space-y-4">
                                    {enrolledCourses.slice(0, 3).map((course, idx) => (
                                        <div key={idx} className="flex items-center gap-4 p-4 bg-muted/30 rounded-2xl border border-border/50 hover:bg-muted/50 transition-all group cursor-pointer" onClick={() => navigate(`/academy/course/${course.id}`)}>
                                            <div className="w-12 h-12 rounded-xl bg-primary/10 flex items-center justify-center text-primary group-hover:scale-110 transition-transform">
                                                <Icon name="Play" size={20} />
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <p className="text-sm font-black italic truncate uppercase">{course.title}</p>
                                                <p className="text-[10px] font-bold text-muted-foreground uppercase">{course.instructor}</p>
                                            </div>
                                            <div className="text-right">
                                                <p className="text-xs font-black italic text-secondary">{course.progress}%</p>
                                            </div>
                                        </div>
                                    ))}
                                    {enrolledCourses.length === 0 && (
                                        <div className="text-center py-12 opacity-40">
                                            <Icon name="Search" size={40} className="mx-auto mb-4" />
                                            <p className="text-xs font-black italic uppercase tracking-widest">No active courses found</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Announcements Feed */}
                        <div className="max-w-4xl">
                            <AnnouncementFeed enrolledCourseIds={enrolledCourses.map(c => c.id)} />
                        </div>
                    </div>
                );
            case 'learning':
                return (
                    <div className="space-y-8 animate-in fade-in duration-500">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {enrolledCourses.map((course, idx) => (
                                <div key={idx} className="bg-card border border-border rounded-[2.5rem] p-6 shadow-sm hover:shadow-xl transition-all group overflow-hidden relative">
                                    <div className="flex gap-6">
                                        <div className="w-24 h-24 rounded-2xl bg-muted overflow-hidden shrink-0 border border-border/50">
                                            {course.thumbnail ? (
                                                <img src={course.thumbnail} alt={course.title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center bg-primary/5 text-primary">
                                                    <Icon name="GraduationCap" size={32} />
                                                </div>
                                            )}
                                        </div>
                                        <div className="flex-1 min-w-0 flex flex-col justify-between">
                                            <div>
                                                <span className="text-[10px] font-black uppercase tracking-widest text-secondary mb-1 block">{course.achievementLabel}</span>
                                                <h3 className="text-lg font-black italic tracking-tighter uppercase leading-tight truncate">{course.title}</h3>
                                                <p className="text-xs text-muted-foreground font-bold italic">By {course.instructor}</p>
                                            </div>
                                            <div className="space-y-2 mt-4">
                                                <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-tighter">
                                                    <span className="text-muted-foreground">Progress</span>
                                                    <span className="text-secondary">{course.progress}%</span>
                                                </div>
                                                <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                                                    <div className="h-full bg-secondary transition-all duration-1000" style={{ width: `${course.progress}%` }} />
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="mt-6 flex gap-3">
                                        <Button variant="secondary" fullWidth onClick={() => navigate(`/academy/course/${course.id}`)} className="rounded-xl h-11 font-black italic uppercase text-[10px] tracking-widest">CONTINUE</Button>
                                        <Button variant="ghost" className="rounded-xl h-11 px-4 border border-border" onClick={() => navigate(`/academy/course/${course.id}`)}><Icon name="ArrowRight" size={18} /></Button>
                                    </div>
                                </div>
                            ))}
                            {enrolledCourses.length === 0 && (
                                <div className="col-span-full py-24 text-center bg-muted/20 rounded-[3rem] border-2 border-dashed border-border/50">
                                    <Icon name="GraduationCap" size={60} className="mx-auto mb-6 text-muted-foreground/30" />
                                    <h3 className="text-xl font-black italic uppercase tracking-tighter">Your Academy is empty</h3>
                                    <p className="text-muted-foreground font-medium mb-8">Start your learning journey by exploring our elite catalog.</p>
                                    <Button variant="primary" onClick={() => navigate('/academy')} className="rounded-2xl px-8 font-black italic uppercase tracking-widest h-14 shadow-xl shadow-primary/20">EXPLORE ACADEMY</Button>
                                </div>
                            )}
                        </div>
                    </div>
                );
            case 'goals': return <GoalCenter />;
            case 'badges': return (
                <div className="space-y-12 animate-in fade-in duration-500">
                    <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-6">
                        {/* Logic for badges could be expanded here */}
                        <div className="aspect-square bg-card border border-border rounded-[2.5rem] p-6 flex flex-col items-center justify-center text-center gap-3 group hover:scale-105 transition-all cursor-pointer opacity-30 grayscale">
                            <div className="p-4 bg-muted rounded-2xl text-muted-foreground group-hover:bg-primary/10 group-hover:text-primary transition-colors">
                                <Icon name="Award" size={32} />
                            </div>
                            <p className="text-[10px] font-black uppercase tracking-widest leading-tight">Master Scholar</p>
                        </div>
                        {/* More placeholders or actual badge logic */}
                    </div>
                </div>
            );
            case 'gear': return <FoundersGear assessmentScores={courseProgress} enrolledCourses={enrolledCourses} userId={user?.id} />;
            case 'study-mates': return <StudyMateHub userId={user?.id} />;
            case 'project-squads': return <ProjectSquadHub userId={user?.id} />;
            case 'referral': return <ReferralDashboard userId={user?.id} />;
            case 'saved':
                return (
                    <div className="space-y-8 animate-in fade-in duration-500">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {savedOpportunities?.map((opp, idx) => (
                                <div key={idx} className="bg-card border border-border rounded-[2.5rem] p-6 shadow-sm hover:shadow-xl transition-all group overflow-hidden" onClick={() => navigate(`/opportunity-detail/${opp.id}`)}>
                                    <div className="flex items-start justify-between mb-6">
                                        <div className="p-3 bg-primary/10 rounded-2xl text-primary"><Icon name="Briefcase" size={24} /></div>
                                        <button className="text-muted-foreground hover:text-red-500 transition-colors"><Icon name="Heart" size={20} className="fill-red-500 text-red-500" /></button>
                                    </div>
                                    <h3 className="text-xl font-black italic tracking-tighter uppercase leading-tight mb-2 group-hover:text-primary transition-colors">{opp.title}</h3>
                                    <p className="text-xs font-bold text-muted-foreground italic mb-6">{opp.organization || 'Global Institution'}</p>
                                    <div className="flex items-center gap-2">
                                        <span className="px-3 py-1 bg-muted rounded-full text-[9px] font-black uppercase tracking-widest">{opp.category}</span>
                                        <span className="text-[9px] font-black uppercase tracking-widest text-muted-foreground/60 ml-auto">{new Date(opp.savedAt).toLocaleDateString()}</span>
                                    </div>
                                </div>
                            ))}
                            {(!savedOpportunities || savedOpportunities.length === 0) && (
                                <div className="col-span-full py-24 text-center bg-muted/20 rounded-[3rem] border-2 border-dashed border-border/50">
                                    <Icon name="Bookmark" size={60} className="mx-auto mb-6 text-muted-foreground/30" />
                                    <h3 className="text-xl font-black italic uppercase tracking-tighter">No saved opportunities</h3>
                                    <p className="text-muted-foreground font-medium mb-8">Save items to your dashboard to track them here.</p>
                                    <Button variant="primary" onClick={() => navigate('/opportunity-discovery')} className="rounded-2xl px-8 font-black italic uppercase tracking-widest h-14">DISCOVER OPPORTUNITIES</Button>
                                </div>
                            )}
                        </div>
                    </div>
                );
            case 'luc-wallet': return <LUCWallet userId={user?.id} />;
            default: return null;
        }
    };

    const allTabs = navigationGroups.flatMap(g => g.tabs);

    const handleUnenroll = async (e, course) => {
        e.stopPropagation();
        if (!window.confirm(`Are you sure you want to unenroll from "${course.title}"?\n\nWARNING: You will permanently lose all progress and certifications for this course.`)) return;

        try {
            await supabaseService.unenrollStudent(user.id, course.id);
            addToast('Successfully unenrolled from course.', 'success');
            setTimeout(() => window.location.reload(), 1500);
        } catch (error) {
            addToast('Failed to unenroll.', 'error');
        }
    };

    const handleClaimCertificate = async (course) => {
        try {
            const certData = await supabaseService.issueCertificate(user.id, course.id, course.instructor_id);
            setSelectedCert({
                uid: certData.certificate_uid,
                student_name: user?.name || 'Scholar',
                course_title: course.title,
                instructor_name: course.instructor,
                issue_date: certData.issue_date
            });
            setIsCertModalOpen(true);
        } catch (error) {
            addToast('Failed to issue certificate.', 'error');
        }
    };

    const [studentBookings, setStudentBookings] = useState([]);
    useEffect(() => {
        if (user) {
            supabaseService.getStudentBookings(user.id).then(data => setStudentBookings(data || []));
        }
    }, [user]);

    return (
        <div className="min-h-screen bg-background flex flex-col font-sans selection:bg-primary/30 overflow-hidden">
            <Header />

            <div className="flex-1 flex overflow-hidden">
                {/* ... existing sidebar and main structure ... */}
                {/* Mobile Sidebar Overlay */}
                <AnimatePresence>
                    {isSidebarOpen && (
                    <motion.div 
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 bg-background/80 backdrop-blur-sm z-40 lg:hidden"
                        onClick={() => setIsSidebarOpen(false)}
                    />
                    )}
                </AnimatePresence>

                {/* Sidebar Navigation */}
                <aside className={cn(
                    "fixed lg:static top-16 sm:top-20 lg:top-0 left-0 z-50 w-72 bg-card border-r border-border transition-all duration-500 ease-in-out flex flex-col h-[calc(100vh-4rem)] sm:h-[calc(100vh-5rem)] lg:h-[calc(100vh-6rem)] shadow-2xl lg:shadow-none",
                    isSidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'
                )}>
                    <div className="p-8 relative">
                        <h2 className="text-2xl font-black italic tracking-tighter flex items-center gap-3">
                            <div className="p-2 bg-secondary/10 rounded-lg">
                                <Icon name="GraduationCap" size={20} className="text-secondary" />
                            </div>
                            STUDENT HUB
                        </h2>
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground mt-2 opacity-60">Elite Scholar Command</p>
                    </div>

                    <nav className="flex-1 overflow-y-auto custom-scrollbar px-4 pb-12 space-y-8">
                        {navigationGroups.map((group, idx) => (
                            <div key={idx} className="space-y-2">
                                <h3 className="px-4 text-[9px] font-black uppercase tracking-[0.3em] text-secondary/40 mb-3">
                                    {group.group}
                                </h3>
                                <div className="space-y-1">
                                    {group.tabs.map((tab) => (
                                        <button
                                            key={tab.id}
                                            onClick={() => {
                                                setActiveTab(tab.id);
                                                setIsSidebarOpen(false);
                                            }}
                                            className={cn(
                                                "w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-xs font-black italic transition-all duration-300 relative group",
                                                activeTab === tab.id 
                                                    ? 'text-secondary' 
                                                    : 'text-muted-foreground hover:text-foreground hover:bg-muted/50'
                                            )}
                                        >
                                            {activeTab === tab.id && (
                                                <motion.div 
                                                    layoutId="activeTabStudent"
                                                    className="absolute inset-0 bg-secondary/5 border border-secondary/20 rounded-2xl -z-10"
                                                    transition={{ type: "spring", bounce: 0.2, duration: 0.6 }}
                                                />
                                            )}
                                            <Icon 
                                                name={tab.icon} 
                                                size={18} 
                                                className={cn(
                                                    "transition-colors",
                                                    activeTab === tab.id ? "text-secondary" : "group-hover:text-secondary"
                                                )} 
                                            />
                                            <span className="uppercase tracking-widest">{tab.label}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </nav>

                    <div className="p-4 border-t border-border">
                        <div className="p-4 bg-muted/30 rounded-2xl flex items-center gap-3">
                            <div className="w-10 h-10 bg-secondary/20 rounded-full flex items-center justify-center font-black italic text-secondary">
                                {user?.name?.charAt(0) || 'S'}
                            </div>
                            <div className="min-w-0">
                                <p className="text-[10px] font-black italic truncate">{user?.name || 'Scholar'}</p>
                                <p className="text-[8px] text-muted-foreground font-bold uppercase truncate">Learning Journey</p>
                            </div>
                        </div>
                    </div>
                </aside>

                {/* Main Content Area */}
                <main className="flex-1 overflow-y-auto custom-scrollbar h-[calc(100vh-4rem)] sm:h-[calc(100vh-5rem)] lg:h-[calc(100vh-6rem)] bg-muted/5 relative">
                    
                    {/* Mobile Sidebar Toggle - Dynamic Handle */}
                    <motion.button 
                        initial={{ opacity: 0 }}
                        animate={{ 
                            opacity: 1,
                            x: isSidebarOpen ? 288 : 0
                        }}
                        transition={{ type: "spring", damping: 20, stiffness: 100 }}
                        whileHover={{ scale: 1.1 }}
                        whileTap={{ scale: 0.9 }}
                        className="lg:hidden fixed left-0 top-[45%] z-[60] p-3 pr-4 bg-secondary text-white rounded-r-3xl shadow-2xl shadow-secondary/40 flex items-center justify-center border-y border-r border-white/10 transition-colors"
                        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                    >
                        <Icon name={isSidebarOpen ? "ChevronLeft" : "ChevronRight"} size={24} />
                    </motion.button>

                    <div className="max-w-7xl mx-auto p-4 sm:p-8 lg:p-12">
                        {/* Page Header */}
                        <div className="mb-12">
                            <div className="flex flex-col gap-3">
                                <div className="flex items-center gap-3">
                                    <div className="h-1 w-12 bg-secondary rounded-full" />
                                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-secondary">Student Command Center</span>
                                </div>
                                <h1 className="text-4xl md:text-5xl font-black italic tracking-tighter uppercase leading-none">
                                    {allTabs.find(t => t.id === activeTab)?.label}
                                </h1>
                                <p className="text-muted-foreground font-bold italic text-sm md:text-base max-w-2xl opacity-70">
                                    {activeTab === 'overview' && 'A comprehensive view of your academic progress and institutional standing.'}
                                    {activeTab === 'learning' && 'Access and manage your comprehensive course catalog and certifications.'}
                                    {activeTab === 'goals' && 'Configure and track your strategic learning objectives and milestones.'}
                                    {activeTab === 'badges' && 'Your earned institutional accolades and recognition of excellence.'}
                                </p>
                            </div>
                        </div>

                        {/* Content Area */}
                        <div className="min-h-[60vh] relative">
                            <AnimatePresence mode="wait">
                                <motion.div
                                    key={activeTab}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    exit={{ opacity: 0, y: -10 }}
                                    transition={{ duration: 0.3, ease: "easeOut" }}
                                >
                                    {renderTabContent()}
                                </motion.div>
                            </AnimatePresence>
                        </div>
                    </div>
                    <Footer />
                </main>
            </div>
            
            <CertificateViewer 
                isOpen={isCertModalOpen} 
                onClose={() => setIsCertModalOpen(false)} 
                certificate={selectedCert} 
            />
        </div>
    );
};

export default StudentDashboard;
