import React, { useState, useEffect } from 'react';
import { supabaseService } from '../../../services/supabaseService';
import { useToast } from '../../../contexts/ToastContext';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

const SpotlightManagement = () => {
    const { addToast } = useToast();
    const [spotlights, setSpotlights] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isAdding, setIsAdding] = useState(false);
    
    // Form state
    const [recipientEmail, setRecipientEmail] = useState('');
    const [title, setTitle] = useState('Student of the Week');
    const [rewardAmount, setRewardAmount] = useState('100');
    const [periodLabel, setPeriodLabel] = useState('');
    const [summary, setSummary] = useState('');

    useEffect(() => {
        fetchSpotlights();
        // Set default period label (e.g., "Week 17, 2026")
        const now = new Date();
        const weekNum = Math.ceil(now.getDate() / 7);
        const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
        if (title === 'Student of the Week') {
            setPeriodLabel(`Week ${weekNum}, ${monthNames[now.getMonth()]} ${now.getFullYear()}`);
            setRewardAmount('100');
        } else {
            setPeriodLabel(`${monthNames[now.getMonth()]} ${now.getFullYear()}`);
            setRewardAmount('500');
        }
    }, [title]);

    const fetchSpotlights = async () => {
        setIsLoading(true);
        try {
            // We'll need a new method in supabaseService
            const { data, error } = await supabaseService.supabase
                .from('student_spotlights')
                .select(`
                    *,
                    profiles:user_id (full_name, avatar_url)
                `)
                .order('created_at', { ascending: false });
            
            if (error) throw error;
            setSpotlights(data || []);
        } catch (error) {
            console.error("Error fetching spotlights:", error);
            addToast("Failed to load spotlights", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const handleCreateSpotlight = async (e) => {
        e.preventDefault();
        setIsAdding(true);
        try {
            // 1. Find user ID by email
            const { data: userData, error: userError } = await supabaseService.supabase
                .from('profiles')
                .select('id')
                .eq('email', recipientEmail.trim().toLowerCase())
                .single();
            
            if (userError || !userData) {
                addToast("User not found with that email", "error");
                return;
            }

            // 2. Insert spotlight
            const { error: insertError } = await supabaseService.supabase
                .from('student_spotlights')
                .insert([{
                    user_id: userData.id,
                    title,
                    period_label: periodLabel,
                    achievement_summary: summary,
                    reward_amount: parseFloat(rewardAmount)
                }]);
            
            if (insertError) {
                if (insertError.code === '23505') {
                    addToast(`A winner already exists for ${periodLabel} (${title})`, "warning");
                } else {
                    throw insertError;
                }
            } else {
                addToast(`${title} crowned successfully!`, "success");
                setRecipientEmail('');
                setSummary('');
                fetchSpotlights();
            }
        } catch (error) {
            console.error("Error creating spotlight:", error);
            addToast("Failed to create spotlight", "error");
        } finally {
            setIsAdding(false);
        }
    };

    const handleDelete = async (id) => {
        if (!window.confirm("Are you sure you want to remove this spotlight? (This will NOT revoke the credits already awarded)")) return;
        
        try {
            const { error } = await supabaseService.supabase
                .from('student_spotlights')
                .delete()
                .eq('id', id);
            
            if (error) throw error;
            addToast("Spotlight record removed", "info");
            fetchSpotlights();
        } catch (error) {
            addToast("Failed to delete", "error");
        }
    };

    return (
        <div className="space-y-8 p-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-black text-primary italic">HALL OF FAME MANAGEMENT</h2>
                    <p className="text-sm text-muted-foreground">Select and reward the champions of the LUC community.</p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Form Section */}
                <div className="lg:col-span-1">
                    <form onSubmit={handleCreateSpotlight} className="bg-card border border-border rounded-[2rem] p-8 shadow-xl space-y-6 sticky top-24">
                        <div className="flex items-center gap-3 mb-2">
                            <div className="w-10 h-10 rounded-2xl bg-primary/10 flex items-center justify-center text-primary">
                                <Icon name="Award" size={20} />
                            </div>
                            <h3 className="font-black italic">CROWN A WINNER</h3>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Recipient Email</label>
                                <input 
                                    type="email"
                                    required
                                    placeholder="scholar@example.com"
                                    value={recipientEmail}
                                    onChange={(e) => setRecipientEmail(e.target.value)}
                                    className="w-full h-12 px-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-xl outline-none transition-all text-sm font-medium"
                                />
                            </div>

                            <div>
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Spotlight Title</label>
                                <select 
                                    value={title}
                                    onChange={(e) => setTitle(e.target.value)}
                                    className="w-full h-12 px-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-xl outline-none transition-all text-sm font-medium"
                                >
                                    <option>Student of the Week</option>
                                    <option>Student of the Month</option>
                                </select>
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Period Label</label>
                                    <input 
                                        type="text"
                                        required
                                        placeholder="e.g. Week 17"
                                        value={periodLabel}
                                        onChange={(e) => setPeriodLabel(e.target.value)}
                                        className="w-full h-12 px-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-xl outline-none transition-all text-sm font-medium"
                                    />
                                </div>
                                <div>
                                    <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">LUC Reward</label>
                                    <input 
                                        type="number"
                                        required
                                        value={rewardAmount}
                                        onChange={(e) => setRewardAmount(e.target.value)}
                                        className="w-full h-12 px-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-xl outline-none transition-all text-sm font-black"
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="text-[10px] font-black uppercase tracking-widest text-muted-foreground ml-1">Achievement Summary</label>
                                <textarea 
                                    required
                                    rows="3"
                                    placeholder="Briefly describe why this student was chosen..."
                                    value={summary}
                                    onChange={(e) => setSummary(e.target.value)}
                                    className="w-full p-4 bg-muted/50 border-2 border-transparent focus:border-primary/20 rounded-xl outline-none transition-all text-sm font-medium resize-none"
                                />
                            </div>
                        </div>

                        <Button 
                            type="submit"
                            fullWidth
                            loading={isAdding}
                            className="h-14 bg-primary text-white font-black italic rounded-xl shadow-lg shadow-primary/20"
                        >
                            CROWN CHAMPION
                        </Button>
                    </form>
                </div>

                {/* List Section */}
                <div className="lg:col-span-2">
                    <div className="bg-card border border-border rounded-[2rem] overflow-hidden shadow-xl">
                        <div className="p-6 border-b border-border bg-muted/20 flex items-center justify-between">
                            <h3 className="font-black italic text-sm">SPOTLIGHT HISTORY</h3>
                            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">{spotlights.length} Records</span>
                        </div>

                        <div className="divide-y divide-border">
                            {isLoading ? (
                                <div className="py-20 flex justify-center">
                                    <Icon name="Loader2" size={32} className="animate-spin text-primary opacity-50" />
                                </div>
                            ) : spotlights.length === 0 ? (
                                <div className="py-20 text-center opacity-50">
                                    <Icon name="Award" size={40} className="mx-auto mb-4" />
                                    <p className="font-bold">No champions crowned yet.</p>
                                </div>
                            ) : (
                                spotlights.map(item => (
                                    <div key={item.id} className="p-6 hover:bg-muted/30 transition-colors group">
                                        <div className="flex items-start justify-between">
                                            <div className="flex gap-4">
                                                <div className="w-12 h-12 rounded-2xl overflow-hidden border border-border shadow-sm">
                                                    <img 
                                                        src={item.profiles?.avatar_url || `https://ui-avatars.com/api/?name=${item.profiles?.full_name}&background=random`} 
                                                        alt="Winner" 
                                                        className="w-full h-full object-cover"
                                                    />
                                                </div>
                                                <div>
                                                    <div className="flex items-center gap-2">
                                                        <p className="font-black text-primary italic">{item.profiles?.full_name || 'Deleted User'}</p>
                                                        <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded-md ${item.title.includes('Month') ? 'bg-amber-500/20 text-amber-600' : 'bg-indigo-500/20 text-indigo-600'}`}>
                                                            {item.title}
                                                        </span>
                                                    </div>
                                                    <p className="text-[10px] text-muted-foreground font-bold mt-0.5">{item.period_label}</p>
                                                    <p className="text-xs text-muted-foreground mt-2 italic line-clamp-2">"{item.achievement_summary}"</p>
                                                    <div className="flex items-center gap-3 mt-3">
                                                        <span className="text-[10px] font-black text-emerald-500 bg-emerald-500/10 px-2 py-0.5 rounded-md">
                                                            +{item.reward_amount} LUC
                                                        </span>
                                                        <span className="text-[9px] text-muted-foreground">
                                                            Crowned on {new Date(item.created_at).toLocaleDateString()}
                                                        </span>
                                                    </div>
                                                </div>
                                            </div>
                                            <button 
                                                onClick={() => handleDelete(item.id)}
                                                className="p-2 text-muted-foreground hover:text-red-500 opacity-0 group-hover:opacity-100 transition-all"
                                            >
                                                <Icon name="Trash2" size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SpotlightManagement;
