import React from 'react';
import { LineChart, Line, AreaChart, Area, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const AnalyticsChart = ({ title, data, type = 'line', dataKey, secondDataKey, color = '#4A90A4', secondColor = '#10B981' }) => {
  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload?.length) {
      return (
        <div className="bg-card border border-border rounded-lg p-3 shadow-lg">
          <p className="text-sm font-medium text-foreground mb-2">{label}</p>
          <div className="space-y-1.5">
            {payload.map((entry, index) => (
                <div key={index} className="flex items-center justify-between gap-4">
                    <span className="text-xs text-muted-foreground flex items-center gap-1.5">
                        <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: entry.color }} />
                        {entry.name}:
                    </span>
                    <span className="text-sm font-bold text-foreground">{entry.value.toLocaleString()}</span>
                </div>
            ))}
          </div>
        </div>
      );
    }
    return null;
  };

  const renderChart = () => {
    const commonProps = {
      data,
      margin: { top: 10, right: 10, left: 0, bottom: 0 }
    };

    const xAxisKey = data?.[0]?.date ? 'date' : 'name';

    switch (type) {
      case 'area':
        return (
          <AreaChart {...commonProps}>
            <defs>
              <linearGradient id={`color${dataKey}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={color} stopOpacity={0.3} />
                <stop offset="95%" stopColor={color} stopOpacity={0} />
              </linearGradient>
              {secondDataKey && (
                <linearGradient id={`color${secondDataKey}`} x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor={secondColor} stopOpacity={0.3} />
                    <stop offset="95%" stopColor={secondColor} stopOpacity={0} />
                </linearGradient>
              )}
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border)" vertical={false} />
            <XAxis dataKey={xAxisKey} stroke="var(--color-muted-foreground)" style={{ fontSize: '10px' }} tickLine={false} axisLine={false} />
            <YAxis stroke="var(--color-muted-foreground)" style={{ fontSize: '10px' }} tickLine={false} axisLine={false} />
            <Tooltip content={<CustomTooltip />} />
            <Area type="monotone" name={dataKey === 'total' ? 'Total Visits' : dataKey} dataKey={dataKey} stroke={color} strokeWidth={2} fillOpacity={1} fill={`url(#color${dataKey})`} />
            {secondDataKey && (
                <Area type="monotone" name={secondDataKey === 'scholars' ? 'Scholars' : secondDataKey} dataKey={secondDataKey} stroke={secondColor} strokeWidth={2} fillOpacity={1} fill={`url(#color${secondDataKey})`} />
            )}
          </AreaChart>
        );
      case 'bar':
        return (
          <BarChart {...commonProps}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border)" vertical={false} />
            <XAxis dataKey={xAxisKey} stroke="var(--color-muted-foreground)" style={{ fontSize: '10px' }} tickLine={false} axisLine={false} />
            <YAxis stroke="var(--color-muted-foreground)" style={{ fontSize: '10px' }} tickLine={false} axisLine={false} />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey={dataKey} fill={color} radius={[4, 4, 0, 0]} />
            {secondDataKey && <Bar dataKey={secondDataKey} fill={secondColor} radius={[4, 4, 0, 0]} />}
          </BarChart>
        );
      default:
        return (
          <LineChart {...commonProps}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border)" vertical={false} />
            <XAxis dataKey={xAxisKey} stroke="var(--color-muted-foreground)" style={{ fontSize: '10px' }} tickLine={false} axisLine={false} />
            <YAxis stroke="var(--color-muted-foreground)" style={{ fontSize: '10px' }} tickLine={false} axisLine={false} />
            <Tooltip content={<CustomTooltip />} />
            <Line type="monotone" dataKey={dataKey} stroke={color} strokeWidth={3} dot={false} activeDot={{ r: 6 }} />
            {secondDataKey && <Line type="monotone" dataKey={secondDataKey} stroke={secondColor} strokeWidth={3} dot={false} activeDot={{ r: 6 }} />}
          </LineChart>
        );
    }
  };

  return (
    <div className="bg-card rounded-2xl p-4 md:p-6 shadow-[0_4px_12px_rgba(27,54,93,0.08)]">
      <h3 className="text-lg md:text-xl font-semibold text-foreground mb-4">{title}</h3>
      <div className="w-full h-64 md:h-80" aria-label={`${title} Chart`}>
        <ResponsiveContainer width="100%" height="100%">
          {renderChart()}
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default AnalyticsChart;