import React from 'react';
import { useSelector } from 'react-redux';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';

const SuccessStories = () => {
  const stories = useSelector((state) => state.content.successStories);

  return (
    <section id="success-stories" className="py-12 md:py-16 lg:py-20 bg-gradient-to-br from-[var(--color-primary)]/5 to-[var(--color-secondary)]/5">
      <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8">
        <div className="text-center mb-8 md:mb-12">
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-success)]/10 text-[var(--color-success)] rounded-full mb-4">
            <Icon name="Star" size={20} />
            <span className="text-sm md:text-base font-semibold">Community Success Stories</span>
          </div>
          <h2 className="text-2xl md:text-3xl lg:text-4xl font-bold text-[var(--color-primary)] mb-3 md:mb-4">
            Your Success is Our Community's Success
          </h2>
          <p className="text-sm md:text-base lg:text-lg text-[var(--color-muted-foreground)] max-w-2xl mx-auto">
            Real stories from real people who transformed their lives through opportunities discovered on LUC
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 md:gap-8">
          {stories?.map((story) => (
            <div
              key={story?.id}
              className="bg-[var(--color-card)] rounded-2xl p-6 md:p-8 shadow-[var(--shadow-card)] hover:shadow-[var(--shadow-elevated)] transition-all duration-300 hover:-translate-y-1 border border-[var(--color-border)]"
            >
              <div className="flex items-start gap-4 mb-6">
                <div className="relative flex-shrink-0">
                  <div className="w-16 h-16 md:w-20 md:h-20 rounded-full overflow-hidden ring-4 ring-[var(--color-accent)]/20">
                    <Image
                      src={story?.image}
                      alt={story?.imageAlt}
                      className="w-full h-full object-cover"
                    />
                  </div>
                  <div className="absolute -bottom-1 -right-1 w-8 h-8 bg-[var(--color-success)] rounded-full flex items-center justify-center border-4 border-[var(--color-card)]">
                    <Icon name="CheckCircle" size={16} color="white" />
                  </div>
                </div>

                <div className="flex-1 min-w-0">
                  <h3 className="text-lg md:text-xl font-bold text-[var(--color-primary)] mb-1">
                    {story?.name}
                  </h3>
                  <p className="text-sm md:text-base text-[var(--color-secondary)] font-semibold line-clamp-1">
                    {story?.achievement}
                  </p>
                </div>
              </div>

              <div className="mb-6">
                <div className="flex items-center gap-2 mb-3">
                  <Icon name="Quote" size={20} className="text-[var(--color-accent)]" />
                  <span className="text-xs md:text-sm font-semibold text-[var(--color-muted-foreground)]">Success Story</span>
                </div>
                <p className="text-sm md:text-base text-[var(--color-foreground)] leading-relaxed line-clamp-4">
                  {story?.story}
                </p>
              </div>

              <div className="space-y-3 pt-4 border-t border-[var(--color-border)]">
                <div className="flex items-center gap-2 text-xs md:text-sm text-[var(--color-muted-foreground)]">
                  <Icon name="Award" size={16} className="text-[var(--color-accent)]" />
                  <span className="line-clamp-1">{story?.opportunity}</span>
                </div>
                <div className="flex items-center justify-between text-xs md:text-sm text-[var(--color-muted-foreground)]">
                  <div className="flex items-center gap-2">
                    <Icon name="MapPin" size={14} />
                    <span>{story?.country}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Icon name="Calendar" size={14} />
                    <span>{story?.year}</span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>


      </div>
    </section>
  );
};

export default SuccessStories;