    // --- Course Chat Helpers ---
    async joinCourseChat(userId, courseId) {
        // Use the RPC to handle join/create logic securely on the server
        // This bypasses RLS issues during the 'initial' creation of the group
        const { data, error } = await supabase.rpc('join_course_group', { 
            p_course_id: courseId.toString() 
        });

        if (error) {
            console.error("Failed to join course chat via RPC:", error);
            throw error;
        }
        return data;
    },

    async leaveCourseChat(userId, courseId) {
        const { data: channel } = await supabase
            .from('chat_channels')
            .select('id')
            .eq('type', 'course')
            .eq('content_id', courseId.toString())
            .maybeSingle();
        
        if (channel) {
            await supabase
                .from('chat_channel_members')
                .delete()
                .eq('channel_id', channel.id)
                .eq('user_id', userId);
        }
    },

    async syncCourseChats() {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return;

        // 1. Ensure in General Chat (Hardcoded ID used in GlobalChat)
        const generalId = '00000000-0000-0000-0000-000000000000';
        const { data: generalChannel } = await supabase
            .from('chat_channels')
            .select('id')
            .eq('id', generalId)
            .maybeSingle();
        
        if (generalChannel) {
            await supabase
                .from('chat_channel_members')
                .upsert({ channel_id: generalId, user_id: user.id }, { onConflict: 'channel_id,user_id' });
        }

        // 2. Ensure in all enrolled course chats
        const { data: enrollments } = await supabase
            .from('enrollments')
            .select('item_id')
            .eq('user_id', user.id);
        
        if (enrollments) {
            for (const enrollment of enrollments) {
                await this.joinCourseChat(user.id, enrollment.item_id);
            }
        }
    },

    async postToCourseChat(courseId, message) {
        // 1. Find the channel
        const { data: channel } = await supabase
            .from('chat_channels')
            .select('id')
            .eq('type', 'course')
            .eq('content_id', courseId.toString())
            .maybeSingle();
            
        if (channel) {
            return await this.sendMessage(channel.id, message);
        }
        return null;
    },

