    async createLiveSession(sessionData) {
        // Generate a human-readable slug from the title
        let meetingId = (sessionData.title || 'brainstorm')
            .toLowerCase()
            .replace(/[^\w\s-]/g, '') // Remove special chars
            .replace(/\s+/g, '-')      // Replace spaces with hyphens
            .replace(/-+/g, '-')       // Remove double hyphens
            .trim();
        
        // Check if this ID is already in use
        const { data: existing } = await supabase
            .from('live_sessions')
            .select('id')
            .eq('meeting_id', meetingId)
            .maybeSingle();

        // If it's taken, add a short random suffix
        if (existing) {
            const uniqueSuffix = Math.random().toString(36).substring(2, 6);
            meetingId = `${meetingId}-${uniqueSuffix}`;
        }

        const { data, error } = await supabase
            .from('live_sessions')
            .insert([{ 
                ...sessionData, 
                meeting_id: meetingId,
                host_id: (await supabase.auth.getUser()).data.user.id
            }])
            .select()
            .single();
        if (error) throw error;
        return data;
    },

